import{_ as e,o as a,c as r,a2 as o}from"./chunks/framework.Crpw6aS5.js";const p=JSON.parse('{"title":"错误坦诚与认错文化 Mistakes & Transparency","description":"巴菲特如何公开认错：从范妮梅到GEICO信用卡，坦诚是智慧不是软弱","frontmatter":{"title":"错误坦诚与认错文化 Mistakes & Transparency","description":"巴菲特如何公开认错：从范妮梅到GEICO信用卡，坦诚是智慧不是软弱"},"headers":[],"relativePath":"02_concepts/mistakes.md","filePath":"02_concepts/mistakes.md"}'),l={name:"02_concepts/mistakes.md"};function s(n,t,i,h,d,g){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="错误坦诚与认错文化-mistakes-transparency" tabindex="-1">错误坦诚与认错文化 Mistakes &amp; Transparency <a class="header-anchor" href="#错误坦诚与认错文化-mistakes-transparency" aria-label="Permalink to &quot;错误坦诚与认错文化 Mistakes &amp; Transparency&quot;">​</a></h1><blockquote><p>在商业世界里，巴菲特对自身错误的坦诚程度极为罕见。从1991年的范妮梅到2008年的爱尔兰银行，他每年都会在致股东信中主动披露自己的错误。这不是软弱，而是他投资哲学最独特的组成部分。</p></blockquote><hr><h2 id="核心出处" tabindex="-1">核心出处 <a class="header-anchor" href="#核心出处" aria-label="Permalink to &quot;核心出处&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">年份</th><th style="text-align:left;">错误事件</th><th style="text-align:left;">核心教训</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><a href="/01_letters/1991年/翻译.html">1991年翻译</a></strong></td><td style="text-align:left;">范妮梅，少赚14亿美元</td><td style="text-align:left;">&quot;我本可以更聪明，但没行动&quot;</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/1994年/翻译.html">1994年翻译</a></strong></td><td style="text-align:left;">USAir投资错误</td><td style="text-align:left;">&quot;非受迫性失误——傲慢+草率分析&quot;</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/1995年/翻译.html">1995年翻译</a></strong></td><td style="text-align:left;">吉列优先股，少赚6.25亿美元</td><td style="text-align:left;">&quot;最大的财务报表外错误&quot;</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/1997年/翻译.html">1997年翻译</a></strong></td><td style="text-align:left;">发行股票换股收购</td><td style="text-align:left;">&quot;用伯克希尔股票换股几乎永远不会合算&quot;</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/1998年/翻译.html">1998年翻译</a></strong></td><td style="text-align:left;">卖出麦当劳</td><td style="text-align:left;">&quot;在公开市场做波段操作比买入伟大企业还糟糕&quot;</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2001年/翻译.html">2001年翻译</a></strong></td><td style="text-align:left;">通用再保险定价灾难</td><td style="text-align:left;">&quot;我违反了诺亚法则&quot;</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2005年/翻译.html">2005年翻译</a></strong></td><td style="text-align:left;">Dexter收购，4.33亿美元</td><td style="text-align:left;">&quot;最糟糕的收购，放大了错误&quot;</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2008年/翻译.html">2008年翻译</a></strong></td><td style="text-align:left;">GEICO信用卡、爱尔兰银行、康菲石油</td><td style="text-align:left;">&quot;我只是更年长，而非更睿智&quot;</td></tr></tbody></table><hr><h2 id="一、认错传统的形成" tabindex="-1">一、认错传统的形成 <a class="header-anchor" href="#一、认错传统的形成" aria-label="Permalink to &quot;一、认错传统的形成&quot;">​</a></h2><p>巴菲特的认错传统始于1991年。在那之前，他已经犯了很多错误，但很少公开承认。</p><p>1991年，他在所罗门兄弟危机处理中深刻体会到：<strong>正直和透明是最好的策略</strong>。从那以后，他开始在每年致股东信中专门列出&quot;我们做错了什么&quot;。</p><p>这一传统后来成为伯克希尔年报中最独特的部分——没有哪家大公司会在年报中如此坦诚地讨论自己的错误。</p><hr><h2 id="二、错误分类-七种典型失误" tabindex="-1">二、错误分类：七种典型失误 <a class="header-anchor" href="#二、错误分类-七种典型失误" aria-label="Permalink to &quot;二、错误分类：七种典型失误&quot;">​</a></h2><p>通过70年全文翻译，可以归纳巴菲特犯过的七类典型错误：</p><h3 id="_1-看对了但没行动-范妮梅-1991年" tabindex="-1">1. 看对了但没行动（范妮梅，1991年） <a class="header-anchor" href="#_1-看对了但没行动-范妮梅-1991年" aria-label="Permalink to &quot;1. 看对了但没行动（范妮梅，1991年）&quot;">​</a></h3><p><strong>情形</strong>：巴菲特完全看懂了范妮梅公司的价值，CEO也很出色，但涨了20%就停止建仓，最终少赚14亿美元。</p><p><strong>教训</strong>：&quot;分析对了但没有行动，比分析错了还让人懊恼。&quot;</p><h3 id="_2-傲慢导致的错误-usair-1994年" tabindex="-1">2. 傲慢导致的错误（USAir，1994年） <a class="header-anchor" href="#_2-傲慢导致的错误-usair-1994年" aria-label="Permalink to &quot;2. 傲慢导致的错误（USAir，1994年）&quot;">​</a></h3><p><strong>情形</strong>：1990年买入3.58亿美元USAir优先股，1994年减值75%至8,950万。错误在于忽视了低成本航空公司的结构性破坏力。</p><p><strong>教训</strong>：&quot;非受迫性失误——我傲慢了，草率地认为航空公司的商业模式会持续。&quot;</p><h3 id="_3-选择错误证券形式-吉列优先股-1995年" tabindex="-1">3. 选择错误证券形式（吉列优先股，1995年） <a class="header-anchor" href="#_3-选择错误证券形式-吉列优先股-1995年" aria-label="Permalink to &quot;3. 选择错误证券形式（吉列优先股，1995年）&quot;">​</a></h3><p><strong>情形</strong>：1989年选择优先股而非普通股，少赚6.25亿美元。</p><p><strong>教训</strong>：&quot;最大的财务报表外错误——我选择了错误的工具来执行正确的想法。&quot;</p><h3 id="_4-发行股票收购-1997年" tabindex="-1">4. 发行股票收购（1997年） <a class="header-anchor" href="#_4-发行股票收购-1997年" aria-label="Permalink to &quot;4. 发行股票收购（1997年）&quot;">​</a></h3><p><strong>情形</strong>：用伯克希尔股票换股收购，公开承认&quot;这是错误&quot;。</p><p><strong>教训</strong>：&quot;用伯克希尔股票换股几乎永远不会合算，因为我们拥有一系列真正了不起的企业。&quot;</p><h3 id="_5-卖出优秀企业-麦当劳-1998年" tabindex="-1">5. 卖出优秀企业（麦当劳，1998年） <a class="header-anchor" href="#_5-卖出优秀企业-麦当劳-1998年" aria-label="Permalink to &quot;5. 卖出优秀企业（麦当劳，1998年）&quot;">​</a></h3><p><strong>情形</strong>：卖出麦当劳股票，试图做波段操作。</p><p><strong>教训</strong>：&quot;在公开市场做波段操作比买入伟大企业还糟糕——我违反了&#39;不想持十年就别持十分钟&#39;的原则。&quot;</p><h3 id="_6-行业判断错误-dexter-2005年" tabindex="-1">6. 行业判断错误（Dexter，2005年） <a class="header-anchor" href="#_6-行业判断错误-dexter-2005年" aria-label="Permalink to &quot;6. 行业判断错误（Dexter，2005年）&quot;">​</a></h3><p><strong>情形</strong>：1993年以4.33亿美元收购制鞋企业Dexter，2001年减值至零。</p><p><strong>教训</strong>：&quot;最糟糕的收购——我买进了一个好价格，但这个business本身是错的。再聪明的人也无法让错误的业务变好。&quot;</p><h3 id="_7-宏观时机错误-康菲石油-爱尔兰银行-2008年" tabindex="-1">7. 宏观时机错误（康菲石油+爱尔兰银行，2008年） <a class="header-anchor" href="#_7-宏观时机错误-康菲石油-爱尔兰银行-2008年" aria-label="Permalink to &quot;7. 宏观时机错误（康菲石油+爱尔兰银行，2008年）&quot;">​</a></h3><p><strong>情形</strong>：油价高峰买入康菲石油（&quot;我在别人贪婪时也贪婪了&quot;），爱尔兰银行股票亏损89%（2.44亿→2,700万）。</p><p><strong>教训</strong>：&quot;我只是更年长，而非更睿智。&quot;</p><hr><h2 id="三、认错的方法论" tabindex="-1">三、认错的方法论 <a class="header-anchor" href="#三、认错的方法论" aria-label="Permalink to &quot;三、认错的方法论&quot;">​</a></h2><p>巴菲特的认错有几个共同特征：</p><p><strong>1. 具体数字</strong>：每个错误都有具体的亏损或机会成本金额 <strong>2. 诚实归因</strong>：不找借口，直接承认是判断失误或傲慢 <strong>3. 提炼教训</strong>：每个错误都有可执行的后续教训 <strong>4. 不影响信心</strong>：认错不等于失去信心，巴菲特从不因为错误而改变核心方法</p><hr><h2 id="四、诺亚法则-知道风险但没行动" tabindex="-1">四、诺亚法则：知道风险但没行动 <a class="header-anchor" href="#四、诺亚法则-知道风险但没行动" aria-label="Permalink to &quot;四、诺亚法则：知道风险但没行动&quot;">​</a></h2><p>2001年，巴菲特在反思通用再保险的定价灾难时，首次提到了&quot;诺亚法则&quot;：</p><blockquote><p>&quot;我违反了诺亚法则：我让伯克希尔以危险的风险水平运营。&quot;</p></blockquote><p>诺亚法则的核心：</p><blockquote><p>&quot;预测下雨不算数；建造方舟才算数。&quot;</p></blockquote><p>知道风险存在，但不采取行动，等于没有真正理解风险。</p><hr><h2 id="五、认错文化的价值" tabindex="-1">五、认错文化的价值 <a class="header-anchor" href="#五、认错文化的价值" aria-label="Permalink to &quot;五、认错文化的价值&quot;">​</a></h2><p>为什么巴菲特如此坦诚地认错？</p><p><strong>对股东</strong>：建立信任，让投资者知道管理层是诚实的 <strong>对自己</strong>：每年整理错误清单，帮助避免重复同样的错误 <strong>对读者</strong>：这是最有价值的投资教育素材——别人犯过的错误比成功经验更有学习价值</p><hr><h2 id="相关主题" tabindex="-1">相关主题 <a class="header-anchor" href="#相关主题" aria-label="Permalink to &quot;相关主题&quot;">​</a></h2><ul><li><a href="./safety-margin.html">安全边际 Safety Margin</a> — 避免错误是保护复利的最好方式</li><li><a href="./long-term.html">长期主义 Long-term</a> — 频繁犯错是因为过度关注短期</li><li><a href="./reputation.html">声誉 Reputation</a> — 坦诚认错反而增强声誉</li></ul>',52)])])}const q=e(l,[["render",s]]);export{p as __pageData,q as default};
